import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/theme/app_colors.dart';import '../../../core/theme/app_typography.dart';import '../../../core/widgets/app_button.dart';import '../../../models/service_model.dart';import '../../../providers/service_provider.dart';class AdminServicesTab extends StatelessWidget {  const AdminServicesTab({super.key});  void _showServiceDialog(BuildContext context, {ServiceModel? service}) {    final nameCtrl = TextEditingController(text: service?.name ?? '');    final descCtrl = TextEditingController(text: service?.description ?? '');    final catCtrl = TextEditingController(text: service?.category ?? 'Hair');    final priceCtrl = TextEditingController(text: service?.price.toString() ?? '');    final durationCtrl = TextEditingController(text: service?.duration.toString() ?? '');    showDialog(      context: context,      builder: (ctx) => AlertDialog(        title: Text(service == null ? 'Add Service' : 'Edit Service'),        content: SingleChildScrollView(          child: Column(            mainAxisSize: MainAxisSize.min,            children: [              TextField(controller: nameCtrl, decoration: const InputDecoration(labelText: 'Service Name')),              TextField(controller: catCtrl, decoration: const InputDecoration(labelText: 'Category (Hair, Skin, etc.)')),              TextField(                controller: priceCtrl,                keyboardType: TextInputType.number,                decoration: const InputDecoration(labelText: 'Price (₹ INR)'),              ),              TextField(                controller: durationCtrl,                keyboardType: TextInputType.number,                decoration: const InputDecoration(labelText: 'Duration (Mins)'),              ),              TextField(controller: descCtrl, decoration: const InputDecoration(labelText: 'Description')),            ],          ),        ),        actions: [          TextButton(onPressed: () => Navigator.of(ctx).pop(), child: const Text('Cancel')),          AppButton(            label: 'Save',            height: 38,            onPressed: () async {              if (nameCtrl.text.isNotEmpty && priceCtrl.text.isNotEmpty && durationCtrl.text.isNotEmpty) {                final newService = ServiceModel(                  serviceId: service?.serviceId ?? 'service_${DateTime.now().millisecondsSinceEpoch}',                  name: nameCtrl.text.trim(),                  description: descCtrl.text.trim(),                  category: catCtrl.text.trim(),                  price: double.tryParse(priceCtrl.text) ?? 0.0,                  duration: int.tryParse(durationCtrl.text) ?? 45,                  image: service?.image ?? 'https://images.unsplash.com/photo-1562322140-8baeececf3df?w=500',                  isActive: service?.isActive ?? true,                  branchAvailability: service?.branchAvailability ?? ['all'],                );                await context.read<ServiceProvider>().saveService(newService);                if (ctx.mounted) Navigator.of(ctx).pop();              }            },          ),        ],      ),    );  }  void _toggleServiceStatus(BuildContext context, ServiceModel service) {    showDialog(      context: context,      builder: (ctx) => AlertDialog(        title: Text(service.isActive ? 'Deactivate Service?' : 'Activate Service?'),        content: Text(          service.isActive              ? 'Are you sure you want to deactivate ${service.name}? It will not be bookable.'              : 'Are you sure you want to activate ${service.name}?',        ),        actions: [          TextButton(onPressed: () => Navigator.of(ctx).pop(), child: const Text('Cancel')),          AppButton(            label: 'Confirm',            height: 38,            onPressed: () async {              final updated = ServiceModel(                serviceId: service.serviceId,                name: service.name,                description: service.description,                category: service.category,                price: service.price,                duration: service.duration,                image: service.image,                isActive: !service.isActive,                branchAvailability: service.branchAvailability,              );              await context.read<ServiceProvider>().saveService(updated);              if (ctx.mounted) Navigator.of(ctx).pop();            },          ),        ],      ),    );  }  @override  Widget build(BuildContext context) {    final serviceProv = context.watch<ServiceProvider>();    return Scaffold(      body: ListView.builder(        padding: const EdgeInsets.all(16),        itemCount: serviceProv.services.length,        itemBuilder: (ctx, i) {          final s = serviceProv.services[i];          return Card(            margin: const EdgeInsets.only(bottom: 12),            child: ListTile(              leading: Icon(                Icons.spa,                color: s.isActive ? AppColors.primary : Colors.grey,              ),              title: Text(                s.name,                style: AppTypography.titleMedium.copyWith(                  color: s.isActive ? AppColors.textPrimary : Colors.grey,                ),              ),              subtitle: Text('${s.category} • ${s.duration} mins\n₹${s.price.toStringAsFixed(0)}'),              trailing: PopupMenuButton<String>(                onSelected: (val) {                  if (val == 'edit') {                    _showServiceDialog(context, service: s);                  } else if (val == 'toggle') {                    _toggleServiceStatus(context, s);                  }                },                itemBuilder: (ctx) => [                  const PopupMenuItem(value: 'edit', child: Text('Edit')),                  PopupMenuItem(                    value: 'toggle',                    child: Text(s.isActive ? 'Deactivate' : 'Activate'),                  ),                ],              ),              isThreeLine: true,            ),          );        },      ),      floatingActionButton: FloatingActionButton.extended(        backgroundColor: AppColors.primary,        foregroundColor: Colors.white,        onPressed: () => _showServiceDialog(context),        icon: const Icon(Icons.add),        label: const Text('Add Service'),      ),    );  }}